import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { Loading } from '../../../components';
import { useFormik } from "formik";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { ToastContainer, toast } from "react-toastify";
import useApi from "../../../hooks/useApi";
import countiesApi from "../../../api/countiesApi";
import { updateOtherOrderDetails } from "../../../helpers/retailerHelpers";



export default function ShippingAddressModal({ openEditModal, setopenEditModal, shippingDetails, setshippingDetails, selectedOrder, setselectedOrder }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();



    const [errors, setErrors] = useState();


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            contact_person_name: '',
            contact_person_phone: '',
            estate: '',
            road: '',
            city: '',
            region: '',
        },

        validationSchema: Yup.object({
            shipping_cost: Yup.number().min(0)
                .required().label('Shipping cost'),
            contact_person_name: Yup.string()
                .required().label('Contact person name'),
            contact_person_phone: Yup.string()
                .required().label('Contact person phone'),
            city: Yup.string()
                .required().label('City'),
            road: Yup.string()
                .required().label('Road'),
            region: Yup.object()
                .required().label('County'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            setselectedOrder(updateOtherOrderDetails(selectedOrder.draft_id, { shipping_cost: values.shipping_cost }))
            setopenEditModal(false)

            const delivery_details = {
                "contact_person_name": values.contact_person_name,
                "contact_person_phone": values.contact_person_phone,
                "estate": values.estate,
                "city": values.city,
                "region": values.region.value,
                "road": values.road
            }

            setshippingDetails(delivery_details)
        },
    });


    //Retrieve counties
    const [counties, setCounties] = useState([])
    const countiesActionsApi = useApi(countiesApi.countiesAction)
    const getCounties = async () => {
        await countiesActionsApi.request({
            "action": "GetCounties"

        })
    }

    useEffect(() => {
        getCounties()
    }, [])

    useEffect(() => {

        if (countiesActionsApi.data && countiesActionsApi.data.length > 0) {

            setCounties(countiesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }

    }, [countiesActionsApi.data])




    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                {countiesActionsApi.loading ? <Loading loading={countiesActionsApi.loading} /> : <ModalContent>

                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1  items-center">Shipping  Details</ModalHeader>
                                <ModalBody className="overflow-y-scroll">
                                    <Input
                                        id="shipping_cost"
                                        name="shipping_cost"
                                        autoFocus
                                        label="Shipping Cost"
                                        placeholder="Enter shipping cost"
                                        variant="bordered"
                                        type="number"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.shipping_cost}
                                        value={formik.values.shipping_cost}
                                        color={formik.errors.shipping_cost ? "danger" : "grey"}
                                        errorMessage={formik.errors.shipping_cost}
                                    />

                                    <Input
                                        id="contact_person_name"
                                        name="contact_person_name"
                                        autoFocus
                                        label="Recipient name"
                                        placeholder="Enter contact person name"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.contact_person_name}
                                        value={formik.values.contact_person_name}
                                        color={formik.errors.contact_person_name ? "danger" : "grey"}
                                        errorMessage={formik.errors.contact_person_name}
                                    />

                                    <Input
                                        id="contact_person_phone"
                                        name="contact_person_phone"
                                        autoFocus
                                        label="Recipient phone"
                                        placeholder="Enter contact person phone"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.contact_person_phone}
                                        value={formik.values.contact_person_phone}
                                        color={formik.errors.contact_person_phone ? "danger" : "grey"}
                                        errorMessage={formik.errors.contact_person_phone}
                                    />

                                    <Input
                                        id="city"
                                        name="city"
                                        autoFocus
                                        label="Recipient's residence town"
                                        placeholder="Enter town name"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.city}
                                        value={formik.values.city}
                                        color={formik.errors.city ? "danger" : "grey"}
                                        errorMessage={formik.errors.city}
                                    />

                                    <Input
                                        id="road"
                                        name="road"
                                        autoFocus
                                        label="Recipient road"
                                        placeholder="Delivery road name"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.road}
                                        value={formik.values.road}
                                        color={formik.errors.road ? "danger" : "grey"}
                                        errorMessage={formik.errors.road}
                                    />

                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="region"
                                            key="region"
                                            name="region"
                                            components={animatedComponent}
                                            placeholder="Select delivery region"
                                            isClearable
                                            value={formik.values.region}
                                            onChange={(value) => formik.setFieldValue("region", value)}
                                            options={counties}
                                        />
                                        {formik.touched.region && formik.errors.region ? (
                                            <p className="text-red-500">{formik.errors.region}</p>
                                        ) : null}
                                    </div>
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>


                        </>
                    )}
                </ModalContent>}
            </Modal>
        </>
    );
}
