class RetailerReceipt {
  constructor(
    id,
    title,
    is_drug,
    received_from,
    received_from_title,
    product,
    product_title,
    preparation,
    preparation_title,
    manufacturer,
    manufacturer_title,
    category,
    category_title,
    sub_category,
    sub_category_title,
    retailer_variation,
    retailer_order,
    retailer_order_item,
    batch,
    manufacture_date,
    expiry_date,
    pack_buying_price,
    pack_selling_price,
    unit_buying_price,
    unit_selling_price,
    pack_quantity,
    unit_quantity,
    price_discount,
    price_discount_title,
    quantity_discount,
    quantity_discount_title,
    units_per_pack,
    image
  ) {
    this.id = id;
    this.title = title;
    this.is_drug = is_drug;
    this.received_from = received_from;
    this.received_from_title = received_from_title;
    this.product = product;
    this.product_title = product_title;
    this.preparation = preparation;
    this.preparation_title = preparation_title;
    this.manufacturer = manufacturer;
    this.manufacturer_title = manufacturer_title;
    this.category = category;
    this.category_title = category_title;
    this.sub_category = sub_category;
    this.sub_category_title = sub_category_title;
    this.retailer_variation = retailer_variation;
    this.retailer_order = retailer_order;
    this.retailer_order_item = retailer_order_item;
    this.batch = batch;
    this.manufacture_date = manufacture_date;
    this.expiry_date = expiry_date;
    this.pack_buying_price = pack_buying_price;
    this.pack_selling_price = pack_selling_price;
    this.unit_buying_price = unit_buying_price;
    this.unit_selling_price = unit_selling_price;
    this.pack_quantity = pack_quantity;
    this.unit_quantity = unit_quantity;
    this.price_discount = price_discount;
    this.price_discount_title = price_discount_title;
    this.quantity_discount = quantity_discount;
    this.quantity_discount_title = quantity_discount_title;
    this.units_per_pack = units_per_pack;
    this.image = image;
  }
}

export default RetailerReceipt;
