import React, { useEffect, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import useApi from "../../../hooks/useApi";
import employeesApi from "../../../api/employees/employeesApi";
import {
  createOrderItem,
  retrieveDraftCustomerOrders,
  updateOrderItems,
  removeOrderItem,
  updateOtherOrderDetails,
  deleteDraftOrder,
  updateOrderItemDiscount,
  updateOrderItemQuantity,
} from "../../../helpers/retailerHelpers";
import { SelectorIcon } from "@heroicons/react/solid";
import {
  Avatar,
  Card,
  CardFooter,
  CardHeader,
  CardBody,
  Input,
  Divider,
  Tab,
  Tabs,
  RadioGroup,
} from "@heroui/react";
import {
  CustomInput,
  CustomRadioItem,
  DeleteIcon,
  Loading,
  PlusIcon,
  SearchIcon,
} from "../../../components";
import { AiOutlineShoppingCart } from "react-icons/ai";
import { useStateContext } from "../../../contexts/ContextProvider";
import RequiredQuantityFormModal from "./RequiredQuantityFormModal";
import useScreenSize from "../../../hooks/useScreenSize";
import { ToastContainer, toast } from "react-toastify";
import paymentsApi from "../../../api/paymentsApi";
import { Button } from "@heroui/react";
import ShippingAddressModal from "./ShippingAddressModal";
import MpesaNumberFormModal from "./MpesaNumberFormModal1";
import CounterDiscountFormModal from "./CounterDiscountFormModal";
import CashPaymentFormModal from "./CashPaymentFormModal";
import { formatKenyaPhoneNumber } from "../../../helpers/utils";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";
import {
  DeleteForeverTwoTone,
  DiscountTwoTone,
  Edit,
  RefreshRounded,
} from "@mui/icons-material";
import { useDispatch, useSelector } from "react-redux";
import { getRetailerReceipts } from "../../../redux/retailers/receipts/actions";
import "react-toastify/dist/ReactToastify.css";
import { CardTitle } from "reactstrap";
import { usePageVisibility } from "../../../hooks/userPageVisibility";

function DraftCustomerOrderCart() {
  const [selected, setSelected] = React.useState("products");
  const screenSize = useScreenSize();
  const { draft_id } = useParams();
  const dispatch = useDispatch();
  const retailerReceipts = useSelector(
    (state) => state.RetailerReceipts.retailerReceipts
  );
  const loading = useSelector((state) => state.RetailerReceipts.loading);

  const [employeeId, setemployeeId] = useState();
  const [data, setdata] = useState([]);
  const [errors, setErrors] = useState([]);
  const { currentColor, successColor } = useStateContext();

  const [openShippingAddressModal, setopenShippingAddressModal] =
    useState(false);
  const [shippingDetails, setshippingDetails] = useState();

  const [openMpesaNumberModal, setopenMpesaNumberModal] = useState(false);
  const [mpesaNumber, setmpesaNumber] = useState();

  const [openCashpaymentModal, setopenCashpaymentModal] = useState(false);

  const [openCounterDiscountDialog, setopenCounterDiscountDialog] =
    useState(false);
  const [counterDiscount, setcounterDiscount] = useState();
  const [selectedOrder, setselectedOrder] = useState();
  const [currentEmploymentDetails, setcurrentEmploymentDetails] = useState();
  const [draftCustomerOrders, setdraftCustomerOrders] = useState([]);
  const [openRequiredQuantityModal, setopenRequiredQuantityModal] =
    useState(false);
  // const [retailerReceipts, setRetailerReceipts] = useState([])
  const [quantity, setQuantity] = useState();
  const [unitOfIssue, setunitOfIssue] = useState("PIECE")
  const [selectedRetailerReceipt, setselectedRetailerReceipt] = useState();
  const [selectedOrderItems, setselectedOrderItems] = useState([]);
  const [draftId, setdraftId] = useState(draft_id);
  const [selectedPaymentMethod, setselectedPaymentMethod] = useState(
    selectedOrder && selectedOrder.payment_method
      ? selectedOrder.payment_method
      : ""
  );
  const [selectedDeliveryOption, setselectedDeliveryOption] = useState(
    selectedOrder && selectedOrder.delivery_method
      ? selectedOrder.delivery_method
      : ""
  );
  const [orderTotal, setorderTotal] = useState();
  const [cashbalance, setcashbalance] = useState(0);
  const [tenderedAmount, settenderedAmount] = useState();
  const [selectedOrderItem, setselectedOrderItem] = useState();

  const navigate = useNavigate();
  const getDraftOrders = async () => {
    const drafts = await retrieveDraftCustomerOrders();

    console.log("retrieved drafts", drafts);

    if (drafts) {
      setdraftCustomerOrders(drafts);
    }
  };

  useEffect(() => {
    if (draft_id) setdraftId(draft_id);
  }, [draftId]);

  //Retrieve employment details
  const getCurrentEmploymentDetailsApi = useApi(
    employeesApi.employeesActionJoint
  );
  const getCurrentEmploymentDetails = async () => {
    await getCurrentEmploymentDetailsApi.request({
      action: "CurrentUserEmployment",
    });
  };

  useEffect(() => {
    if (getCurrentEmploymentDetailsApi.data) {
      if (getCurrentEmploymentDetailsApi.data.employee) {
        setemployeeId(getCurrentEmploymentDetailsApi.data.employee.id);
        setcurrentEmploymentDetails(
          getCurrentEmploymentDetailsApi.data.employee
        );
      }
    }

    console.log(
      "getCurrentEmploymentDetailsApi.data",
      getCurrentEmploymentDetailsApi.data
    );
  }, [getCurrentEmploymentDetailsApi.data]);

  useEffect(() => {
    getDraftOrders();
    getCurrentEmploymentDetails();
  }, []);

  //Set selected order
  useEffect(() => {
    if (draftCustomerOrders.length) {
      setselectedOrder(draftCustomerOrders.find((x) => x.draft_id === draftId));
    }
  }, [draftCustomerOrders]);



  useEffect(() => {
    // generateReferenceNumbers()
    // getEntityRetailerReceipts()

    dispatch(getRetailerReceipts({ action: "GetRetailerReceipts" }));
  }, []);

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      dispatch(getRetailerReceipts({ action: "GetRetailerReceipts" }));
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 200000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled]);

  //Selected delivery method
  useEffect(() => {
    if (selectedDeliveryOption) {
      if (selectedDeliveryOption && selectedDeliveryOption === "DELIVERY") {
        //Open shipping details modal
        setopenShippingAddressModal(true);
      } else {
        //Close shipping details modal
        setopenShippingAddressModal(false);
      }

      //Update order delivery option
      setselectedOrder(
        updateOtherOrderDetails(selectedOrder && selectedOrder.draft_id, {
          delivery_method: selectedDeliveryOption,
        })
      );
    }
  }, [selectedDeliveryOption]);

  useEffect(() => {
    if (selectedPaymentMethod) {
      if (selectedPaymentMethod && selectedPaymentMethod === "MOBILE MONEY") {
        setopenMpesaNumberModal(true);
      } else {
        setopenMpesaNumberModal(false);
      }

      if (selectedPaymentMethod && selectedPaymentMethod === "CASH") {
        setorderTotal(
          selectedOrderItems &&
            selectedOrderItems
              .reduce((acc, item) => acc + item.item_price_total, 0)
              .toFixed(2)
        );
        setopenCashpaymentModal(true);
      } else {
        setopenCashpaymentModal(false);
      }
    }
  }, [selectedPaymentMethod]);

  useEffect(() => {
    setdata(retailerReceipts);
  }, [retailerReceipts]);

  const handleFilter = (e) => {
    const search_param = e.target.value;

    if (
      retailerReceipts &&
      retailerReceipts.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        retailerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(retailerReceipts);
    }
  };

  //Retrieve payment methods
  const [paymentMethods, setpaymentMethods] = useState([]);
  const paymentMethodsActionsApi = useApi(
    paymentsApi.allowePaymentMethodsAction
  );

  const getPaymentMethods = async (data) => {
    await paymentMethodsActionsApi.request(data);
  };

  useEffect(() => {
    if (selectedOrder) {
      getPaymentMethods({
        action: "GetAllowedPaymentMethods",
        entity: selectedOrder.entity,
      });

      console.log("SEL O", selectedOrder);
    }
  }, [selectedOrder]);
  useEffect(() => {
    if (paymentMethodsActionsApi.data && paymentMethodsActionsApi.data.length) {
      setpaymentMethods(paymentMethodsActionsApi.data);
    }

    console.log("paymentMethodsActionsApi.data", paymentMethodsActionsApi.data);
  }, [paymentMethodsActionsApi.data]);

  //Add item to cart
  const handleAddToCart = (item) => {
    setopenRequiredQuantityModal(!openRequiredQuantityModal);
    setselectedRetailerReceipt(item);
  };

  //Remove item for order
  const handleRemoveOrderItem = (item) => {
    console.log("Item", item);
    const order = removeOrderItem(item.draft_id, item.retailer_receipt);
    setselectedOrderItems(order.orderItems);
  };

  //Create order item
  useEffect(() => {
    if (quantity && selectedRetailerReceipt) {
      const orderItem = createOrderItem(
        draftId,
        parseInt(quantity),
        selectedRetailerReceipt,
        unitOfIssue,
      );

      const currentOrderItems = selectedOrderItems;
      console.log("item c", currentOrderItems);

      const exists = selectedOrderItems.find(
        (x) => x.retailer_receipt === orderItem.retailer_receipt
      );

      if (exists) {
        console.log("Iko");
        const without = currentOrderItems.filter(
          (x) => x.retailer_receipt !== orderItem.retailer_receipt
        );
        setselectedOrderItems([...without, orderItem]);
      } else {
        setselectedOrderItems([...currentOrderItems, orderItem]);
        console.log("Hakuna");
      }
    }
  }, [quantity, unitOfIssue, selectedRetailerReceipt, openRequiredQuantityModal]);

  useEffect(() => {
    if (counterDiscount != undefined) {
      setselectedOrder(
        updateOrderItemDiscount(
          selectedOrder.draft_id,
          counterDiscount,
          selectedOrderItem
        )
      );
    }
  }, [counterDiscount]);

  //Update order items on local storage
  useEffect(() => {
    if (draftId && selectedOrderItems && selectedOrderItems.length > 0) {
      const updated = updateOrderItems(draftId, selectedOrderItems);

      setQuantity(null);
      setselectedRetailerReceipt(null);
    }
  }, [selectedOrderItems]);

  useEffect(() => {
    if (selectedOrder) {
      setselectedOrderItems(selectedOrder.orderItems);
    }
  }, [selectedOrder]);
  useEffect(() => {
    console.log("selectedDeliveryOption", selectedDeliveryOption);
  }, [selectedDeliveryOption]);
  useEffect(() => {
    console.log("selectedPaymentMethod", selectedPaymentMethod);
  }, [selectedPaymentMethod]);

  useEffect(() => {
    console.log("mpesaNumber", mpesaNumber);
  }, [mpesaNumber]);

  const handleSelectPaymentOption = (e) => {
    const payment_method = paymentMethods.find((x) => x.id === e.target.value);
    if (payment_method) {
      setselectedPaymentMethod(payment_method.title);
      const data = {
        payment_method: payment_method,
      };
      setselectedOrder(
        updateOtherOrderDetails(selectedOrder && selectedOrder.draft_id, data)
      );
    }
  };
  const customerOrderActionsApi = useApi(
    customerOrdersApi.customerOrdersStaffAction
  );

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const saveDraftCustomerOrder = async (data) => {
    const result = await customerOrderActionsApi.request(data);
    console.log("res at create order", result);
    if (result.ok) {
      toast.success(result.data.response_message);
      deleteDraftOrder(selectedOrder.draft_id);
      navigate("/retailers/orders");
    } else {
      setErrors(result.data.errors);
    }
  };
  const handleCloseOrder = () => {
    if (!selectedPaymentMethod) {
      toast.error("Select payment method");
    } else {
      console.log("Selected order", selectedOrder);
      console.log("selectedOrderItems", selectedOrderItems);

      const data = {
        action: "CreateCustomerOrder",
        customer_order_details: {
          payment_method_id: selectedOrder.payment_method,
          order_type: selectedOrder.order_type,
          payment_account_number: formatKenyaPhoneNumber(mpesaNumber),
          order_origin: "STAFF",
          customer_id: "",
          customer_name: selectedOrder.customer_name,
          customer_phone: selectedOrder.customer_phone,
          employee_id: employeeId,
          order_items: selectedOrder.orderItems,
          reference_number: selectedOrder.reference_number,
        },
      };

      saveDraftCustomerOrder(data);

      console.log("order data", data);
    }
  };

  const handleUpdateCounterDiscount = (item) => {
    setselectedOrderItem(item);
    setopenCounterDiscountDialog(true);
  };

  const handleEditItemQuantity = (item) => {
    setselectedOrderItem(item);
    setopenRequiredQuantityModal(true);
  };

  useEffect(() => {
    if (quantity && selectedOrderItem) {
      setselectedOrder(
        updateOrderItemQuantity(
          selectedOrder.draft_id,
          quantity,
          selectedOrderItem.retailer_receipt,
          unitOfIssue
        )
      );
      setselectedOrderItem(null);
    }
  }, [quantity, unitOfIssue]);

  return (
    <div>
      {screenSize.width < 768 ? (
        <div>
          <Card className="max-w-full rounded-sm">
            <ToastContainer position="bottom-center" theme="colored" />
            <CardBody className="overflow-hidden">
              <Tabs
                fullWidth
                size="md"
                aria-label="Tabs form"
                selectedKey={selected}
                onSelectionChange={setSelected}
              >
                <Tab key="products" title="Products">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
                    <h1 className="text-large font-bold text-center">
                      Products List
                    </h1>
                    {customerOrderActionsApi.loading ? (
                      <Loading loading={customerOrderActionsApi.loading} />
                    ) : (
                      <Card className="max-w-full mx-1 md:mx-5 my-1">
                        <CardBody>
                          <Input
                            label="Search"
                            isClearable
                            radius="lg"
                            onChange={(e) => handleFilter(e)}
                            classNames={{
                              label: "text-black/50 dark:text-white/90",
                              input: [
                                "bg-transparent",
                                "text-black/90 dark:text-white/90",
                                "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                              ],
                              innerWrapper: "bg-transparent",
                              inputWrapper: [
                                "shadow-xl",
                                "bg-default-200/50",
                                "dark:bg-default/60",
                                "backdrop-blur-xl",
                                "backdrop-saturate-200",
                                "hover:bg-default-200/70",
                                "dark:hover:bg-default/70",
                                "group-data-[focused=true]:bg-default-200/50",
                                "dark:group-data-[focused=true]:bg-default/60",
                                "!cursor-text",
                              ],
                            }}
                            placeholder="Type to search..."
                            startContent={
                              <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                            }
                          />
                        </CardBody>
                      </Card>
                    )}
                    {data &&
                      data.length > 0 &&
                      data.map((item) => (
                        <Card
                          onClick={() => handleAddToCart(item)}
                          className="max-w-full mx-1 md:mx-5 my-2 cursor-pointer"
                        >
                          <CardHeader className="justify-between md:flex-row">
                            <div className="flex gap-5 items-center">
                              <Avatar
                                className="w-20 h-20 text-large"
                                radius="sm"
                                size="lg"
                                src={
                                  item.images && item.images[0]
                                    ? item.images[0].image
                                    : ""
                                }
                                name={item.title}
                              />
                              <div className="flex flex-col gap-1 items-start justify-center">
                                <h4 className="text-medium font-semibold leading-none text-default-600">
                                  {item.title}
                                </h4>
                                <h5 className="text-medium tracking-tight text-default-400">
                                  KES {item.unit_selling_price}
                                </h5>
                                <h6 className="text-medium tracking-tight text-default-400">
                                  In Stock: {item.current_unit_quantity}
                                </h6>
                              </div>
                            </div>
                            <AiOutlineShoppingCart
                              onClick={() => handleAddToCart(item)}
                              className="cursor-pointer hover:resize-x"
                              size={24}
                              color={
                                selectedOrder &&
                                selectedOrder.orderItems &&
                                selectedOrder.orderItems.length &&
                                selectedOrder.orderItems &&
                                selectedOrder.orderItems.length &&
                                selectedOrder.orderItems.filter(
                                  (x) => x.retailer_receipt === item.id
                                ).length > 0
                                  ? successColor
                                  : currentColor
                              }
                            />
                          </CardHeader>
                        </Card>
                      ))}

                    {openRequiredQuantityModal && (
                      <RequiredQuantityFormModal
                        quantity={quantity}
                        setQuantity={setQuantity}
                        unitOfIssue={unitOfIssue}
                        setunitOfIssue={setunitOfIssue}
                        setisModalOpen={setopenRequiredQuantityModal}
                        selectedRetailerReceipt={
                          selectedRetailerReceipt}


                      />
                    )}
                  </div>
                </Tab>
                <Tab key="cart" title="Customer Order">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll my-2">
                    <h1 className="text-large font-bold text-center">
                      Order Summary
                    </h1>
                    <Card className="max-w-full mx-1 md:mx-5 my-1">
                      <CardBody>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-y-2">
                          <div>
                            <p className="text-slate-500">Customer Name</p>
                            <p className="font-bold text-gray-400">
                              {selectedOrder && selectedOrder.customer_name}
                            </p>
                          </div>
                          <div>
                            <p className="text-slate-500">Customer Phone</p>
                            <p className="font-bold text-gray-400">
                              {selectedOrder && selectedOrder.customer_phone}
                            </p>
                          </div>

                          <div>
                            <p className="text-slate-500">Total Amount</p>
                            <p className="font-bold text-gray-400">
                              KES{" "}
                              {selectedOrderItems &&
                                parseFloat(
                                  selectedOrderItems.reduce(
                                    (acc, item) => acc + item.item_price_total,
                                    0
                                  )
                                ).toFixed(2)}
                            </p>
                          </div>

                          <div>
                            <p className="text-slate-500">Items in Order</p>
                            <p className="font-bold text-gray-400">
                              {" "}
                              {selectedOrderItems && selectedOrderItems.length}
                            </p>
                          </div>
                        </div>
                      </CardBody>
                    </Card>
                    {selectedOrderItems.map((item) => (
                      <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                        <CardHeader className="justify-between">
                          <div className="grid md:grid-cols-12 w-full gap-x-2 grid-cols-1">
                            <Avatar
                              className="col-span-1 md:col-span-2"
                              size="lg"
                              radius="sm"
                              src={item.image ? item.image : ""}
                              name={item.title}
                            />
                            <div className="col-span-1  md:col-span-10 flex flex-col gap-y-2 items-start justify-center w-full">
                              <h4 className="text-medium font-semibold leading-none text-default-600">
                                {item.product_title}
                              </h4>

                              <div className="w-full">
                                <p className="font-semibold text-lg border-b-2">
                                  Quantities
                                </p>
                                <div className="flex  justify-between w-full">
                                  {item.purchased_quantity >
                                    item.available_quantity && (
                                    <p className="text-red-500">
                                      <span>Required Quantity: </span>
                                      {item.purchased_quantity ? (
                                        <span>{item.purchased_quantity}</span>
                                      ) : (
                                        <span>0</span>
                                      )}
                                    </p>
                                  )}
                                  {item.purchased_quantity <=
                                    item.available_quantity && (
                                    <p className="text-green-500">
                                      <span>Required Quantity: </span>
                                      {item.purchased_quantity ? (
                                        <span>{item.purchased_quantity}</span>
                                      ) : (
                                        <span>0</span>
                                      )}
                                    </p>
                                  )}

                                  <p>
                                    <span>Available Quantity: </span>
                                    {item.available_quantity ? (
                                      <span>{item.available_quantity}</span>
                                    ) : (
                                      <span>0</span>
                                    )}
                                  </p>
                                  <Edit
                                    onClick={() => handleEditItemQuantity(item)}
                                    className="cursor-pointer"
                                    color="primary"
                                  />
                                  <RefreshRounded
                                    className="cursor-pointer"
                                    color="primary"
                                  />
                                </div>
                              </div>
                              <div className="w-full">
                                <p className="font-semibold text-lg border-b-2">
                                  Pricing
                                </p>
                                <div className="flex  justify-between w-full">
                                  <p>
                                    <span>Unit Selling Price: </span>
                                    {item.unit_selling_price ? (
                                      <span>KES {item.unit_selling_price}</span>
                                    ) : (
                                      <span>KES 0.00</span>
                                    )}
                                  </p>
                                </div>
                              </div>


                              <div className="w-full">
                                <p className="font-semibold text-lg border-b-2">
                                  Item Total Amount
                                </p>
                                <div className="flex  justify-between w-full">
                                  <p>
                                    <span>Item Total: </span>
                                    {item.item_price_total ? (
                                      <span>KES {item.item_price_total}</span>
                                    ) : (
                                      <span>0 %</span>
                                    )}
                                  </p>
                                  <p>
                                    <span>Net Item Total: </span>
                                    {item.item_net_price_total ? (
                                      <span>
                                        KES{" "}
                                        {parseFloat(
                                          item.item_net_price_total
                                        ).toFixed(2)}{" "}
                                      </span>
                                    ) : (
                                      <span>KES 0.00</span>
                                    )}
                                  </p>
                                </div>
                              </div>
                            </div>
                          </div>
                          <div></div>
                        </CardHeader>
                        {/* <CardFooter>
                                                    <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                                        <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                                    </CardFooter> */}
                      </Card>
                    ))}

                    <Card className="max-w-full mx-1 md:mx-5 my-2">
                      <CardBody>
                        <RadioGroup
                          defaultValue={selectedDeliveryOption}
                          onChange={(e) =>
                            setselectedDeliveryOption(e.target.value)
                          }
                          orientation="horizontal"
                          label="Delivery options"
                          description="Selected plan can be changed at any time."
                        >
                          <CustomRadioItem
                            description="Order to be picked up by customer"
                            value="PICKUP"
                          >
                            Pick Up
                          </CustomRadioItem>
                          <CustomRadioItem
                            description="Order to be delivered to customer"
                            value="DELIVERY"
                          >
                            Delivery
                          </CustomRadioItem>
                        </RadioGroup>
                      </CardBody>
                    </Card>

                    <Card className="max-w-full mx-1 md:mx-5 my-2">
                      <CardBody>
                        <RadioGroup
                          defaultValue={selectedPaymentMethod}
                          onChange={(e) => handleSelectPaymentOption(e)}
                          orientation="horizontal"
                          label="Payment Options"
                          description="Payment plan can also be changed after order is saved."
                        >
                          {paymentMethods &&
                            paymentMethods.length &&
                            paymentMethods.map((x) => (
                              <CustomRadioItem
                                description="Order to be delivered to customer"
                                value={x.id}
                              >
                                <Avatar
                                  name={x.title}
                                  src={
                                    x.images && x.images.length
                                      ? x.images[0].image
                                      : ""
                                  }
                                />
                                {x.title}
                              </CustomRadioItem>
                            ))}
                        </RadioGroup>
                      </CardBody>
                    </Card>
                    <Card className="max-w-full mx-1 md:mx-5 my-2 h-3">
                      <Button
                        size={30}
                        onClick={handleCloseOrder}
                        text="Save Order"
                        className="m-1"
                      >
                        Save Order
                      </Button>
                    </Card>
                    {/** {openCashpaymentModal && (
                      <CashPaymentFormModal
                        openEditModal={openCashpaymentModal}
                        setopenEditModal={setopenCashpaymentModal}
                        orderTotal={orderTotal}
                        tenderedAmount={tenderedAmount}
                        setTenderedAmount={settenderedAmount}
                        cashbalance={cashbalance}
                        setcashbalance={setcashbalance}
                      />
                    )}*/ }
                    {openMpesaNumberModal && (
                      <MpesaNumberFormModal
                        openEditModal={openMpesaNumberModal}
                        setopenEditModal={setopenMpesaNumberModal}
                        mpesaNumber={mpesaNumber}
                        setmpesaNumber={setmpesaNumber}
                      />
                    )}
                    {openShippingAddressModal && (
                      <ShippingAddressModal
                        openEditModal={openShippingAddressModal}
                        setopenEditModal={setopenShippingAddressModal}
                        shippingDetails={shippingDetails}
                        setshippingDetails={setshippingDetails}
                        selectedOrder={selectedOrder}
                        setselectedOrder={setselectedOrder}
                      />
                    )}
                    {openRequiredQuantityModal && (
                      <RequiredQuantityFormModal
                        openEditModal={openRequiredQuantityModal}
                        setopenEditModal={setopenRequiredQuantityModal}
                        quantity={quantity}
                        setQuantity={setQuantity}
                      />
                    )}
                  </div>
                </Tab>
              </Tabs>
            </CardBody>
          </Card>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 gap-6">
          {loading ? (
            <Loading loading={loading} />
          ) : (
            <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
              <ToastContainer position="bottom-center" theme="colored" />
              <h1 className="text-large font-bold text-center">
                Products List
              </h1>

              <div className="max-w-full mx-1 md:mx-5  rounded-sm my-5">
                <CustomInput
                  size="large"
                  label="Filter"
                  isClearable
                  onChange={(e) => handleFilter(e)}
                  placeholder="Type to filter..."
                  startContent={
                    <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                  }
                />
              </div>

              {data &&
                data.length > 0 &&
                data.map((item) => (
                  <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                    <CardHeader className="justify-between">
                      <div className="flex gap-5 items-center mx-2 justify-between w-full">
                        <Avatar
                          className="w-20 h-20 text-large"
                          size="lg"
                          radius="sm"
                          src={
                            item.images && item.images[0]
                              ? item.images[0].image
                              : ""
                          }
                          name={item.title}
                        />
                        <div className="flex flex-col items-start justify-center w-full">
                          <h4 className="text-medium font-semibold leading-none text-default-600">
                            {item.title}
                          </h4>

                          <div className="flex flex-row justify-between w-full">
                            <p className="text-medium tracking-tight text-default-400">
                              KES {item.unit_selling_price}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 ">
                              In Stock: {item.current_unit_quantity}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 text-start ">
                              Discount:{" "}
                              {item.unit_price_discount
                                ? item.unit_price_discount
                                : "None"}
                            </p>
                            <p className="text-medium tracking-tight text-default-400 text-start">
                              Net: KES {item.unit_selling_price_discounted}
                            </p>
                          </div>
                          <div className="flex flex-row justify-between w-full">
                            <div className="flex flex-row justify-between">
                              {item.days_to_expiry &&
                              item.days_to_expiry < 90 ? (
                                <h6 className="text-medium tracking-tight text-red-600 pr-3">
                                  Expiry Date:{" "}
                                  {item.expiry_date
                                    ? item.expiry_date
                                    : "Not Indicated"}
                                </h6>
                              ) : (
                                  <h6 className="text-medium tracking-tight pr-3 text-green-600">
                                  Expiry Date:{" "}
                                  {item.expiry_date
                                    ? item.expiry_date
                                    : "Not indicated"}
                                </h6>
                              )}
                              {item.days_to_expiry &&
                              item.days_to_expiry < 90 ? (
                                  <h6 className="text-medium tracking-tight text-red-600 pr-3">
                                  {item.expiry_status}
                                </h6>
                              ) : (
                                <h6 className="text-medium tracking-tight text-green-600">
                                  {item.expiry_status}
                                </h6>
                              )}
                            </div>
                            <div>
                              <AiOutlineShoppingCart
                                onClick={() => handleAddToCart(item)}
                                className="cursor-pointer hover:resize-x"
                                size={36}
                                color={
                                  selectedOrder &&
                                  selectedOrder.orderItems &&
                                  selectedOrder.orderItems.filter(
                                    (x) => x.retailer_receipt === item.id
                                  ).length > 0
                                    ? successColor
                                    : currentColor
                                }
                              />
                            </div>
                          </div>
                        </div>
                      </div>
                    </CardHeader>
                  </Card>
                ))}

              {openRequiredQuantityModal && (
                <RequiredQuantityFormModal
                  openEditModal={openRequiredQuantityModal}
                  setopenEditModal={setopenRequiredQuantityModal}
                  quantity={quantity}
                  setQuantity={setQuantity}
                />
              )}
            </div>
          )}
          <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
            <Card className="max-w-full mx-1 md:mx-5 my-1 rounded-sm">
              <CardHeader>
                <CardTitle className="font-bold text-lg">
                  Order Summary
                </CardTitle>
              </CardHeader>
              <CardBody>
                <div className="grid grid-cols-2 md:grid-cols-4">
                  <div>
                    <p className="text-slate-500">Customer Name</p>
                    <p className="font-bold text-gray-400">
                      {selectedOrder && selectedOrder.customer_name}
                    </p>
                  </div>
                  <div>
                    <p className="text-slate-500">Customer Phone</p>
                    <p className="font-bold text-gray-400">
                      {selectedOrder && selectedOrder.customer_phone}
                    </p>
                  </div>
                  <div>
                    <p className="text-slate-500">Total Amount</p>
                    <p className="font-bold text-gray-400">
                      KES{" "}
                      {selectedOrderItems &&
                        parseFloat(
                          selectedOrderItems.reduce(
                            (acc, item) => acc + item.item_price_total,
                            0
                          )
                        ).toFixed(2)}
                    </p>
                  </div>
                  <div>
                    <p className="text-slate-500">Items in Order</p>
                    <p className="font-bold text-gray-400">
                      {selectedOrderItems && selectedOrderItems.length}
                    </p>
                  </div>
                </div>
              </CardBody>
            </Card>
            {selectedOrderItems &&
              selectedOrderItems.map((item) => (
                <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
                  <CardHeader className="justify-between">
                    <div className="grid md:grid-cols-12 w-full gap-x-2 grid-cols-1">
                      <Avatar
                        className="col-span-2 md:col-span-2 w-full h-full"
                        size="lg"
                        radius="sm"
                        src={item.image ? item.image : ""}
                        name={item.title}
                      />
                      <div className="col-span-1  md:col-span-10 flex flex-col gap-y-2 items-start justify-center w-full">
                        <h4 className="text-medium font-semibold leading-none text-default-600">
                          {item.product_title}
                        </h4>

                        <div className="w-full">
                          <p className="font-semibold text-lg border-b-2">
                            Quantities
                          </p>
                          <div className="flex  justify-between w-full">
                            {item.purchased_quantity >
                              item.available_quantity && (
                              <p className="text-red-500">
                                <span>Required Quantity: </span>
                                {item.purchased_quantity ? (
                                  <span>{item.purchased_quantity}</span>
                                ) : (
                                  <span>0</span>
                                )}
                              </p>
                            )}
                            {item.purchased_quantity <=
                              item.available_quantity && (
                              <p className="text-green-500">
                                <span>Required Quantity: </span>
                                {item.purchased_quantity ? (
                                  <span>{item.purchased_quantity}</span>
                                ) : (
                                  <span>0</span>
                                )}
                              </p>
                            )}

                            <p>
                              <span>Available Quantity: </span>
                              {item.available_quantity ? (
                                <span>{item.available_quantity}</span>
                              ) : (
                                <span>0</span>
                              )}
                            </p>
                            <Edit
                              onClick={() => handleEditItemQuantity(item)}
                              className="cursor-pointer"
                              color="primary"
                            />
                            <RefreshRounded
                              className="cursor-pointer"
                              color="primary"
                            />
                          </div>
                        </div>
                        <div className="w-full">
                          <p className="font-semibold text-lg border-b-2">
                            Pricing
                          </p>
                          <div className="flex  justify-between w-full">
                            <p>
                              <span>Unit Selling Price: </span>
                              {item.unit_selling_price ? (
                                <span>KES {item.unit_selling_price}</span>
                              ) : (
                                <span>KES 0.00</span>
                              )}
                            </p>
                          </div>
                        </div>


                        <div className="w-full">
                          <p className="font-semibold text-lg border-b-2">
                            Item Total Amount
                          </p>
                          <div className="flex  justify-between w-full">
                            <p>
                              <span>Item Total: </span>
                              {item.item_price_total ? (
                                <span>KES {item.item_price_total}</span>
                              ) : (
                                <span>0 %</span>
                              )}
                            </p>
                            <p>
                              <span>Net Item Total: </span>
                              {item.item_net_price_total ? (
                                <span>
                                  KES{" "}
                                  {parseFloat(
                                    item.item_net_price_total
                                  ).toFixed(2)}{" "}
                                </span>
                              ) : (
                                <span>KES 0.00</span>
                              )}
                            </p>
                          </div>
                        </div>
                      </div>
                    </div>
                  </CardHeader>

                  <CardFooter className="flex flex-row justify-between">
                    {/* <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} /> */}
                    {/* <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} /> */}
                    <DiscountTwoTone
                      onClick={() => handleUpdateCounterDiscount(item)}
                      color="success"
                    />
                    <DeleteForeverTwoTone
                      onClick={() => handleRemoveOrderItem(item)}
                      fontSize="large"
                      className="text-red-700 text-lg hover:text-red-400"
                    />
                  </CardFooter>
                </Card>
              ))}

            {/* <Card className='max-w-full mx-1 md:mx-5 my-2'>
                            <CardBody>
                                <RadioGroup defaultValue={selectedDeliveryOption} onChange={(e) => setselectedDeliveryOption(e.target.value)} orientation="horizontal" label="Delivery options" description="Selected plan can be changed at any time.">

                                    <CustomRadioItem description="Order to be picked up by customer" value="PICKUP">
                                        Pick Up
                                    </CustomRadioItem>
                                    <CustomRadioItem description="Order to be delivered to customer" value="DELIVERY">
                                        Delivery
                                    </CustomRadioItem>

                                </RadioGroup>
                            </CardBody>

                        </Card> */}

            <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
              <CardBody>
                <RadioGroup
                  defaultValue={selectedPaymentMethod}
                  onChange={(e) => handleSelectPaymentOption(e)}
                  orientation="horizontal"
                  label="Payment Options"
                  description="Payment plan can also be changed after order is saved."
                >
                  {paymentMethods &&
                    paymentMethods.length &&
                    paymentMethods.map((x) => (
                      <CustomRadioItem description={x.description} value={x.id}>
                        <Avatar
                          name={x.title}
                          src={
                            x.images && x.images.length ? x.images[0].image : ""
                          }
                        />
                        {x.title}
                      </CustomRadioItem>
                    ))}
                </RadioGroup>
              </CardBody>
            </Card>
            <Card className="max-w-full mx-1 md:mx-5 my-2 rounded-sm">
              <Button
                style={{ background: currentColor, color: "white" }}
                size="lg"
                radius="none"
                text="Save Order"
                onClick={handleCloseOrder}
                className="m-1"
              >
                Save Order
              </Button>
            </Card>


            {/* {openShippingAddressModal && <ShippingAddressModal openEditModal={openShippingAddressModal} setopenEditModal={setopenShippingAddressModal} shippingDetails={shippingDetails} setshippingDetails={setshippingDetails} />} */}
            {openRequiredQuantityModal && (
              <RequiredQuantityFormModal
                openEditModal={openRequiredQuantityModal}
                setopenEditModal={setopenRequiredQuantityModal}
                quantity={quantity}
                setQuantity={setQuantity}
              />
            )}

            {openCounterDiscountDialog && (
              <CounterDiscountFormModal
                openCounterDiscountDialog={openCounterDiscountDialog}
                setopenCounterDiscountDialog={setopenCounterDiscountDialog}
                counterDiscount={counterDiscount}
                setcounterDiscount={setcounterDiscount}
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default DraftCustomerOrderCart;
